def check_oracle(harness, controls):
    # each control is an episode whose verdict was fixed in advance
    for episode, expected in controls:
        before = snapshot(episode.environment)
        verdict = harness.score(episode)
        if snapshot(episode.environment) != before:
            raise OracleDefect("scorer changed the state it grades", episode)
        if verdict != expected:
            raise OracleDefect("wrong verdict on a known answer", episode)
